ALTER TABLE public.resumes ADD COLUMN profile_id uuid REFERENCES public.profiles(id);
UPDATE public.resumes r SET profile_id = r.user_id WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = r.user_id);
CREATE FUNCTION public.connect_resume_profile() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.profile_id := NEW.user_id; RETURN NEW; END; $$;
CREATE TRIGGER connect_resume_identity BEFORE INSERT ON public.resumes FOR EACH ROW EXECUTE FUNCTION public.connect_resume_profile();
ALTER TABLE public.analyses ADD COLUMN scorer_version text NOT NULL DEFAULT 'legacy-llm';
CREATE TABLE public.learning_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, skill text NOT NULL, kind text NOT NULL CHECK (kind IN ('course','project','certification')), title text NOT NULL, status text NOT NULL DEFAULT 'not_started' CHECK (status IN ('not_started','in_progress','completed')), resource_url text, evidence_url text, issuer text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, skill, kind, title));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.learning_activities TO authenticated;
GRANT ALL ON public.learning_activities TO service_role;
ALTER TABLE public.learning_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own learning activities" ON public.learning_activities FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.readiness_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, analysis_id uuid NOT NULL REFERENCES public.analyses(id) ON DELETE CASCADE, job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE, match_score integer, scorer_version text NOT NULL, completed_steps integer NOT NULL, total_steps integer NOT NULL, remaining_weeks numeric NOT NULL, source text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.readiness_history TO authenticated;
GRANT ALL ON public.readiness_history TO service_role;
ALTER TABLE public.readiness_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own readiness history" ON public.readiness_history FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.record_readiness(_user uuid, _source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE a record; done_count int; weeks numeric; BEGIN FOR a IN SELECT DISTINCT ON (job_id) * FROM public.analyses WHERE user_id = _user AND status = 'done' AND result IS NOT NULL ORDER BY job_id, created_at DESC LOOP SELECT count(*) FILTER (WHERE l.skill IS NOT NULL), coalesce(sum(CASE WHEN l.skill IS NULL THEN (step->>'estimated_weeks')::numeric ELSE 0 END),0) INTO done_count, weeks FROM jsonb_array_elements(coalesce(a.result->'learning_path','[]'::jsonb)) step LEFT JOIN public.learned_skills l ON l.user_id = _user AND lower(regexp_replace(l.skill,'[[:space:]._-]','','g')) = lower(regexp_replace(step->>'skill','[[:space:]._-]','','g')); INSERT INTO public.readiness_history(user_id,analysis_id,job_id,match_score,scorer_version,completed_steps,total_steps,remaining_weeks,source) VALUES (_user,a.id,a.job_id,a.score,a.scorer_version,done_count,jsonb_array_length(coalesce(a.result->'learning_path','[]'::jsonb)),weeks,_source); END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.record_readiness(uuid,text) FROM PUBLIC, anon, authenticated;
CREATE FUNCTION public.readiness_after_analysis() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.status = 'done' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN PERFORM public.record_readiness(NEW.user_id,'analysis'); END IF; RETURN NEW; END; $$;
CREATE TRIGGER readiness_analysis AFTER INSERT OR UPDATE ON public.analyses FOR EACH ROW EXECUTE FUNCTION public.readiness_after_analysis();
CREATE FUNCTION public.readiness_after_learning() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'DELETE' THEN PERFORM public.record_readiness(OLD.user_id,'learning'); RETURN OLD; END IF; PERFORM public.record_readiness(NEW.user_id,'learning'); RETURN NEW; END; $$;
CREATE TRIGGER readiness_learning AFTER INSERT OR DELETE ON public.learned_skills FOR EACH ROW EXECUTE FUNCTION public.readiness_after_learning();
CREATE TABLE public.market_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), skill text NOT NULL, source text NOT NULL, source_url text NOT NULL, geography text NOT NULL DEFAULT 'India', taxonomy_version text NOT NULL, coverage_key text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, postings integer NOT NULL CHECK (postings >= 0), total_postings integer NOT NULL CHECK (total_postings >= postings), complete boolean NOT NULL DEFAULT false, observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(skill, source, geography, taxonomy_version, coverage_key, period_start, period_end));
GRANT SELECT ON public.market_observations TO authenticated;
GRANT ALL ON public.market_observations TO service_role;
ALTER TABLE public.market_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read licensed aggregates" ON public.market_observations FOR SELECT TO authenticated USING (true);